style.css:
@-moz-document domain("twitter.com"), domain("x.com") {
/* --- Fundo Principal e Cores de Texto --- */
    body {
        background-color: #FFF0F5 !important; /* Lavender Blush (Rosa bem clarinho) */
        color: #6B4E5B !important; /* Texto em tom pastel escuro para combinar */
    }

    /* Linhas divisórias fofas */
    div, article, header, nav {
        border-color: #FFC0CB !important; /* Rosa claro para as bordas */
    }

    /* --- Customização dos Cards e Tweets --- */
    [data-testid="tweet"], 
    [data-testid="placementTracking"] article,
    [data-testid="sidebarColumn"] > div > div > div > div {
        background-color: #FFFFFF !important;
        border-radius: 20px !important; /* Cantos super arredondados */
        margin-bottom: 10px !important;
        box-shadow: 0 4px 10px rgba(255, 182, 193, 0.3) !important; /* Sombra rosa bem sutil */
    }

    /* --- Botões e Elementos Ativos (Rosa Chiclete) --- */
    /* Botão de Tweetar, Links e Ícones de Notificação */
    a[href="/compose/post"], 
    [data-testid="SideNav_NewTweet_Button"],
    div[role="progressbar"] {
        background-color: #FFB6C1 !important; /* Light Pink */
    }
    
    /* Texto dos botões principais */
    a[href="/compose/post"] span, 
    [data-testid="SideNav_NewTweet_Button"] span {
        color: #FFFFFF !important;
    }

    /* Ícones ativos na barra lateral e links */
    nav a svg, 
    nav div[role="button"] svg,
    a {
        color: #FF69B4 !important; /* Hot Pink para os destaques */
    }

    /* --- Barra de Navegação Lateral --- */
    [data-testid="SideNav_AccountMenu_Button"],
    nav a {
        border-radius: 15px !important;
    }
    nav a:hover {
        background-color: #FFE4E1 !important; /* Misty Rose ao passar o mouse */
    }

    /* --- Caixa de Busca e Tendências --- */
    [data-testid="SearchBox_Search_Input_Container"] {
        background-color: #FFE4E1 !important;
        border-radius: 25px !important;
    }
    
    /* Remover o fundo escuro padrão do feed */
    main {
        background-color: #FFF0F5 !important;
    }
    
    /* Ajuste de fontes para um visual mais soft */
    span, time, div {
        font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif !important;
    }
}
